#!/usr/bin/env node
/**
 * Snapshot the live database content into `src/db/seed-data.ts`.
 *
 * The generated file is used by `npm run db:seed` so a fresh database can be
 * restored to exactly today's content. Run from the project root:
 *
 *   npm run db:snapshot
 */
import { writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { loadEnvFile } from "node:process";
import pg from "pg";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
try {
  loadEnvFile(join(root, ".env.local"));
} catch {
  // .env.local is optional; DATABASE_URL may come from the environment.
}

const connectionString = process.env.DATABASE_URL;
if (!connectionString) {
  console.error("DATABASE_URL tidak ditemukan. Buat .env.local dulu.");
  process.exit(1);
}

const client = new pg.Client({
  connectionString,
  ssl: { rejectUnauthorized: false },
});
await client.connect();

const profile = await client.query(
  "select name, initials, url, location, description, summary, avatar_url, email from profile order by id limit 1"
);
const skills = await client.query(
  "select name, icon, sort_order from skills order by sort_order, id"
);
const social = await client.query(
  "select label, url, icon, show_in_navbar, sort_order from social_links order by sort_order, id"
);
const work = await client.query(
  'select company, href, location, title, description, logo_url, "start", "end", sort_order from work_experience order by sort_order, id'
);
const education = await client.query(
  'select school, href, degree, logo_url, "start", "end", sort_order from education order by sort_order, id'
);
const projects = await client.query(
  "select title, href, dates, description, technologies, image_url, video_url, links, active, sort_order from projects order by sort_order, id"
);
await client.end();

const p = profile.rows[0] ?? {
  name: "",
  initials: "",
  url: "",
  location: "",
  description: "",
  summary: "",
  avatar_url: "",
  email: "",
};

const json = (value) => JSON.stringify(value, null, 2);

const skillRows = skills.rows.map((r) => ({
  name: r.name,
  icon: r.icon,
  sortOrder: r.sort_order,
}));
const socialRows = social.rows.map((r) => ({
  label: r.label,
  url: r.url,
  icon: r.icon,
  showInNavbar: r.show_in_navbar,
  sortOrder: r.sort_order,
}));
const workRows = work.rows.map((r) => ({
  company: r.company,
  href: r.href,
  location: r.location,
  title: r.title,
  description: r.description,
  logoUrl: r.logo_url,
  start: r.start,
  end: r.end,
  sortOrder: r.sort_order,
}));
const educationRows = education.rows.map((r) => ({
  school: r.school,
  href: r.href,
  degree: r.degree,
  logoUrl: r.logo_url,
  start: r.start,
  end: r.end,
  sortOrder: r.sort_order,
}));
const projectRows = projects.rows.map((r) => ({
  title: r.title,
  href: r.href,
  dates: r.dates,
  description: r.description,
  technologies: r.technologies ?? [],
  imageUrl: r.image_url,
  videoUrl: r.video_url,
  links: r.links ?? [],
  active: r.active,
  sortOrder: r.sort_order,
}));

const out = `/**
 * Snapshot of the content stored in the database.
 *
 * Generated by \`npm run db:snapshot\` on ${new Date().toISOString()}.
 * Used to seed a fresh database (\`npm run db:seed\`) and as the fallback
 * content when the database is unavailable.
 */

import type { ProjectLink } from "./schema";

export type SeedProfile = {
  name: string;
  initials: string;
  url: string;
  location: string;
  description: string;
  summary: string;
  avatarUrl: string;
  email: string;
};

export type SeedSkill = { name: string; icon: string; sortOrder: number };

export type SeedSocialLink = {
  label: string;
  url: string;
  icon: string;
  showInNavbar: boolean;
  sortOrder: number;
};

export type SeedWork = {
  company: string;
  href: string;
  location: string;
  title: string;
  description: string;
  logoUrl: string;
  start: string;
  end: string;
  sortOrder: number;
};

export type SeedEducation = {
  school: string;
  href: string;
  degree: string;
  logoUrl: string;
  start: string;
  end: string;
  sortOrder: number;
};

export type SeedProject = {
  title: string;
  href: string;
  dates: string;
  description: string;
  technologies: string[];
  imageUrl: string;
  videoUrl: string;
  links: ProjectLink[];
  active: boolean;
  sortOrder: number;
};

export const seedProfile: SeedProfile = ${json({
  name: p.name,
  initials: p.initials,
  url: p.url,
  location: p.location,
  description: p.description,
  summary: p.summary,
  avatarUrl: p.avatar_url,
  email: p.email,
})};

export const seedSkills: SeedSkill[] = ${json(skillRows)};

export const seedSocialLinks: SeedSocialLink[] = ${json(socialRows)};

export const seedWork: SeedWork[] = ${json(workRows)};

export const seedEducation: SeedEducation[] = ${json(educationRows)};

export const seedProjects: SeedProject[] = ${json(projectRows)};
`;

const target = join(root, "src/db/seed-data.ts");
writeFileSync(target, out);
console.log(
  `Snapshot ditulis ke src/db/seed-data.ts ` +
    `(skills: ${skillRows.length}, social: ${socialRows.length}, work: ${workRows.length}, ` +
    `education: ${educationRows.length}, projects: ${projectRows.length})`
);
